<?php
require dirname(__DIR__).'/app/bootstrap.php';require_admin();
$days=(int)($_GET['days']??30);if(!in_array($days,[1,7,30,90],true))$days=30;
$today=new DateTimeImmutable('today',new DateTimeZone('Asia/Dhaka'));
$start=$today->modify('-'.($days-1).' days');$end=$today->modify('+1 day');
$bounds=[$start->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),$end->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s')];
$summary=query("SELECT COUNT(*) AS orders,COALESCE(SUM(o.status='cancelled'),0) AS cancelled,COALESCE(SUM(o.status='pending'),0) AS pending,COALESCE(SUM(o.status='delivered'),0) AS delivered,COALESCE(SUM(o.payment_status='paid' AND o.status<>'cancelled'),0) AS paid_orders,COALESCE(SUM(CASE WHEN o.payment_status='paid' AND o.status<>'cancelled' THEN o.subtotal-COALESCE(d.amount,0) ELSE 0 END),0) AS merchandise,COALESCE(SUM(CASE WHEN o.payment_status='paid' AND o.status<>'cancelled' THEN o.total ELSE 0 END),0) AS collected FROM orders o LEFT JOIN order_discounts d ON d.order_id=o.id WHERE o.created_at>=? AND o.created_at<?",$bounds)->fetch();
$daily=query("SELECT DATE(DATE_ADD(o.created_at,INTERVAL 6 HOUR)) AS day,COUNT(*) AS orders,COALESCE(SUM(CASE WHEN o.payment_status='paid' AND o.status<>'cancelled' THEN o.subtotal-COALESCE(d.amount,0) ELSE 0 END),0) AS revenue FROM orders o LEFT JOIN order_discounts d ON d.order_id=o.id WHERE o.created_at>=? AND o.created_at<? GROUP BY day ORDER BY day",$bounds)->fetchAll();$daily=array_column($daily,null,'day');
$best=query("SELECT i.product_name,SUM(i.quantity) AS units,SUM(i.quantity*i.unit_price) AS gross FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.created_at>=? AND o.created_at<? AND o.payment_status='paid' AND o.status<>'cancelled' GROUP BY i.product_id,i.product_name ORDER BY units DESC,gross DESC LIMIT 10",$bounds)->fetchAll();
$inventory=query('SELECT p.id,p.name,v.size,v.stock FROM products p JOIN variants v ON v.product_id=p.id WHERE p.active=1 ORDER BY p.name,v.id')->fetchAll();
$max=max(array_merge([1],array_values(array_map(fn($row)=>(int)$row['revenue'],$daily))));
render_header('Sales dashboard',true);
?>
<main class="page sales-dashboard"><div class="section-head"><div><p class="eyebrow">FLAWED / BUSINESS OVERVIEW</p><h1>Sales dashboard.</h1></div><a class="back-link" href="<?=url('admin/index.php')?>">MANAGE ORDERS ↗</a></div>
<form class="filters" method="get"><label>Period<select name="days"><?php foreach([1=>'Today',7=>'Last 7 days',30=>'Last 30 days',90=>'Last 90 days'] as $value=>$label):?><option value="<?=$value?>" <?=$days===$value?'selected':''?>><?=$label?></option><?php endforeach ?></select></label><button class="button dark">UPDATE DASHBOARD</button></form>
<p><?=$start->format('j M Y')?> – <?=$today->format('j M Y')?> · Bangladesh time. Refresh this page for the latest figures.</p>
<div class="stats sales-stats"><div><span>Paid merchandise sales</span><strong><?=money($summary['merchandise'])?></strong></div><div><span>Paid order totals · includes delivery</span><strong><?=money($summary['collected'])?></strong></div><div><span>Orders placed</span><strong><?=(int)$summary['orders']?></strong></div><div><span>Paid orders</span><strong><?=(int)$summary['paid_orders']?></strong></div><div><span>Pending / delivered</span><strong><?=(int)$summary['pending']?> / <?=(int)$summary['delivered']?></strong></div><div><span>Cancelled orders</span><strong><?=(int)$summary['cancelled']?></strong></div></div>
<p class="hint">Sales count paid, non-cancelled orders placed in this period. Merchandise sales deduct discounts and exclude delivery. This is an order-date report, not a payment-date or profit report.</p>
<section><h2>Daily sales</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Orders</th><th>Paid merchandise sales</th><th>Trend</th></tr></thead><tbody><?php for($day=$start;$day<$end;$day=$day->modify('+1 day')):$row=$daily[$day->format('Y-m-d')]??['orders'=>0,'revenue'=>0];?><tr><td><?=$day->format('d M')?></td><td><?=(int)$row['orders']?></td><td><?=money($row['revenue'])?></td><td><meter min="0" max="<?=$max?>" value="<?=(int)$row['revenue']?>" aria-label="Paid sales on <?=$day->format('j F')?>"><?=money($row['revenue'])?></meter></td></tr><?php endfor ?></tbody></table></div></section>
<section><h2>Best sellers</h2><p>Paid, non-cancelled orders only. Item value is before order discounts and excludes delivery.</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Units sold</th><th>Item value</th></tr></thead><tbody><?php foreach($best as $row):?><tr><td><?=h($row['product_name'])?></td><td><?=(int)$row['units']?></td><td><?=money($row['gross'])?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$best):?><p>No paid sales in this period yet.</p><?php endif ?></section>
<section><h2>Stock by size</h2><p>Current available stock for visible products, regardless of the selected sales period.</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Size</th><th>Available units</th></tr></thead><tbody><?php foreach($inventory as $row):?><tr><td><a href="<?=url('admin/products.php?id='.$row['id'])?>"><?=h($row['name'])?></a></td><td><?=h($row['size'])?></td><td><?=$row['stock']===null?'Untracked':((int)$row['stock']===0?'Sold out':(int)$row['stock'])?></td></tr><?php endforeach ?></tbody></table></div></section></main><?php render_footer(); ?>
